INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33311, 'John 14:23', 'John', 14, 23, 'عیسی په ځواب کې وویل: «هرڅوک چې زما سره مینه کوي نو هغه به زما په تعلیم باندې عمل کوي. زما پلار به د هغه سره مینه کوي او زه او پلار به هغه ته ورځو او د هغه سره به اوسېږو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_23.mp3', '', 1761754199, 1761754199),
(33312, 'John 14:24', 'John', 14, 24, 'خو څوک چې زما سره مینه نه کوي هغه زما په تعلیم باندې عمل نه کوي. کوم تعلیم چې تاسو یې اورئ هغه زما تعلیم نه دی بلکې زما د پلار تعلیم دی چې زه یې رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_24.mp3', '', 1761754199, 1761754199),
(33313, 'John 14:25', 'John', 14, 25, 'تر هغې پورې چې زه ستاسو سره یم دا خبرې درته کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_25.mp3', '', 1761754199, 1761754199),
(33314, 'John 14:26', 'John', 14, 26, 'خو ستاسو مرسته کوونکی یعنې روح القدس چې پلار به یې زما په نوم راولېږي، هغه به ټول شیان تاسو ته درزده کړي او هرڅه چې ما درته ویلي دي هغه به در په یاد کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_26.mp3', '', 1761754199, 1761754199),
(33315, 'John 14:27', 'John', 14, 27, 'زه تاسو ته سوله درکوم داسې سوله چې یوازې زه یې ورکولای شم. دا د هغې سولې په شان نه ده چې نړۍ یې ورکولای شي. نو څه چې پېښیږي، د هغې په هکله مه نا‌ارامه کېږئ او مه وېرېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_27.mp3', '', 1761754199, 1761754199),
(33316, 'John 14:28', 'John', 14, 28, 'تاسو واورېدل چې ما وویل زه ځم خو بېرته تاسو ته راځم. که چېرې تاسو زما سره مینه کولای نو د دې خبرې په اورېدلو سره چې زه پلار ته ورځم، تاسو به خوشحاله شوي وای، ځکه چې پلار زما نه ډېر لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_28.mp3', '', 1761754199, 1761754199),
(33317, 'John 14:29', 'John', 14, 29, 'مخکې له دې چې دا کار وشي تاسو ته مې وویل نو کله چې دا کار وشي، تاسو به ایمان راوړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_29.mp3', '', 1761754199, 1761754199),
(33318, 'John 14:30', 'John', 14, 30, 'زه نور زیات وخت نه لرم چې ستاسو سره خبرې وکړم، ځکه چې د دې نړۍ واکمن راروان دی. هغه په ما باندې هېڅ واک او اختیار نه لري،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_30.mp3', '', 1761754199, 1761754199),
(33319, 'John 14:31', 'John', 14, 31, 'خو نړۍ باید په دې پوه شي چې زه د پلار سره مینه کوم، نو هماغه کار کوم چې هغه یې راته حکم کوي. اوس راځئ چې د دې ځای نه لاړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john14_verse_31.mp3', '', 1761754199, 1761754199),
(33320, 'Revelation 10:1', 'Revelation', 10, 1, 'بیا ما یوه بله قوي فرښته ولیدله چې د اسمان څخه راښکته کېدله، هغه په ورېځو باندې پوښل شوې وه او په سر باندې یې د بوډۍ ټال ؤ. څېره یې د لمر په شان ځلېدله او پښې یې د اور د پایو په شان وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_1.mp3', '', 1761754199, 1761754199),
(33321, 'Revelation 10:2', 'Revelation', 10, 2, 'د هغې په لاس کې یو کوچنی طومار ؤ چې پرانیستل شوی ؤ. هغې خپله ښي پښه په بحر کې او چپه پښه په ځمکه کېښودله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_2.mp3', '', 1761754199, 1761754199),
(33322, 'Revelation 10:3', 'Revelation', 10, 3, 'هغې د زمري د غړمبار په شان په لوړ اواز چیغه ووهله او کله چې هغې چیغې کړې نو اووه تندرونه وغرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_3.mp3', '', 1761754199, 1761754199),
(33323, 'Revelation 10:4', 'Revelation', 10, 4, 'کله چې هغه اووه تندرونه وغرېدل، نو ما غوښتل چې یو څه ولیکم، خو د اسمان نه یو اواز راغی چې ویل یې: «څه چې هغو اووه تندرونو ویلي دي هغه پټ وساته او هغه مه لیکه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_4.mp3', '', 1761754199, 1761754199),
(33324, 'Revelation 10:5', 'Revelation', 10, 5, 'بیا ما هغه فرښته چې په بحر او وچه ځمکه باندې ولاړه وه ولیدله، هغې خپل ښي لاس اسمان ته پورته کړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_5.mp3', '', 1761754199, 1761754199),
(33325, 'Revelation 10:6', 'Revelation', 10, 6, 'او د هغه چا په نوم یې قسم وخوړ چې تل ترتله ژوندی دی او اسمان، ځمکه، بحر او هرڅه چې په هغو کې دي پیدا کړي دي. هغې وویل: «نور به ځنډ رامنځته نه شي!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_6.mp3', '', 1761754199, 1761754199),
(33326, 'Revelation 10:7', 'Revelation', 10, 7, 'خو په هغه وخت کې کله چې اوومه فرښته خپل سرنی ووهي، نو د خدای پټ راز به پوره شي، لکه څنګه چې هغه خپلو خدمتګارانو یعنې پیغمبرانو ته ویلي وو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_7.mp3', '', 1761754199, 1761754199),
(33327, 'Revelation 10:8', 'Revelation', 10, 8, 'بیا ما یوځل بیا هغه اواز واورېد چې د اسمان نه یې زما سره خبرې کولې او ویل یې: «لاړ شه او د هماغې فرښتې د لاس نه چې په بحر او وچه باندې ولاړه ده، هغه پرانیستل شوی طومار واخله.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_8.mp3', '', 1761754199, 1761754199),
(33328, 'Revelation 10:9', 'Revelation', 10, 9, 'نو زه هغې فرښتې ته ورغلم او ورته مې وویل: «هغه کوچنی طومار ماته راکړه.» هغې وویل: «واخله او ویې خوره، دا به ستا خېټه ترخه کړي، خو خوله به دې لکه د شاتو په شان خوږه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_9.mp3', '', 1761754199, 1761754199),
(33329, 'Revelation 10:10', 'Revelation', 10, 10, 'نو ما هغه کوچنی طومار د فرښتې د لاس نه واخیست او ومې خوړ، هغه زما په خوله کې د شاتو په شان خوږ ولګېده، خو کله چې مې تېر کړ نو زما خېټه یې ترخه کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_10.mp3', '', 1761754199, 1761754199),
(33330, 'Revelation 10:11', 'Revelation', 10, 11, 'بیا راته وویل شول: «ته باید یوځل بیا د خدای پیغام ډېرو خلکو، قومونو، ژبو او پاچاهانو ته ورسوې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation10_verse_11.mp3', '', 1761754199, 1761754199),
(33331, 'Romans 8:1', 'Romans', 8, 1, 'نو اوس چې کوم خلک د عیسی مسیح سره په یووالي کې ژوند کوي، هغوی هېڅ محکوم کېدای نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_1.mp3', '', 1761754199, 1761754199),
(33332, 'Romans 8:2', 'Romans', 8, 2, 'ځکه چې د خدای د روح قانون چې ماته په عیسی مسیح کې ژوندون راکوي، زه یې د ګناه او د مرګ د قانون نه خلاص کړی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_2.mp3', '', 1761754199, 1761754199),
(33333, 'Romans 8:3', 'Romans', 8, 3, 'هغه څه چې شریعت د انساني فطرت د کمزورۍ له امله ونه شو کولای چې سرته یې ورسوي، هغه خدای سرته ورسول. هغه خپل زوی د یو ګناهکار انساني جسم په شکل کې د ګناهونو د بخښنې دپاره راولېږه، ترڅو ګناه په انساني فطرت کې محکومه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_3.mp3', '', 1761754199, 1761754199),
(33334, 'Romans 8:4', 'Romans', 8, 4, 'هغه داسې وکړل د دې دپاره چې د شریعت رښتینې غوښتنې په مونږ کې د نفساني غوښتنو له مخې نه، بلکې د خدای د روح په وسیله چې ژوند کوو، پوره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_4.mp3', '', 1761754199, 1761754199),
(33335, 'Romans 8:5', 'Romans', 8, 5, 'ځکه څوک چې د نفساني غوښتنو له مخې ژوند تېروي، نو تل د نفساني شیانو په فکر کې وي. خو څوک چې د روح القدس د غوښتنو له مخې ژوند کوي، نو هغوی د هغو شیانو په فکر کې وي چې روح القدس یې غواړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_5.mp3', '', 1761754199, 1761754199),
(33336, 'Romans 8:6', 'Romans', 8, 6, 'که چېرې زمونږ په ذهنونو باندې نفساني غوښتنې حاکمې وي، نو پای یې مرګ دی. خو که چېرې زمونږ په ذهنونو باندې روح القدس حاکم وي، نو نتیجه یې ژوند او سوله ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_6.mp3', '', 1761754199, 1761754199),
(33337, 'Romans 8:7', 'Romans', 8, 7, 'ځکه چې خپل ځان د نفساني شیانو پورې تړل د خدای سره دښمني ده، ځکه چې دا د خدای د قانون اطاعت کول نه دي او په حقیقت کې نه شي کولای چې اطاعت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_7.mp3', '', 1761754199, 1761754199),
(33338, 'Romans 8:8', 'Romans', 8, 8, 'څوک چې د خپلو نفساني غوښتنو له مخې ژوند تېروي، هغوی نه شي کولای چې خدای خوشحاله کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_8.mp3', '', 1761754199, 1761754199),
(33339, 'Romans 8:9', 'Romans', 8, 9, 'نو تاسو نور د خپلو نفساني غوښتنو له مخې نه، بلکې د روح القدس د لارښوونې له مخې ژوند کوئ، که په رښتیا سره روح القدس په تاسو کې اوسیږي. که چېرې په چا کې د مسیح روح نه وي، نو هغه د مسیح نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_9.mp3', '', 1761754199, 1761754199),
(33340, 'Romans 8:10', 'Romans', 8, 10, 'خو که چېرې مسیح په تاسو کې اوسیږي، نو که څه هم ستاسو بدن د ګناه له امله مړ هم شي، خو روح القدس تاسو ته ژوند درکوي، ځکه چې تاسو د خدای په نظر کې عادلان ګڼل شوي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_10.mp3', '', 1761754199, 1761754199),
(33341, 'Romans 8:11', 'Romans', 8, 11, 'که چېرې روح القدس چې مسیح یې بېرته د مړو نه راژوندی کړ په تاسو کې اوسي، نو لکه څنګه چې عیسی یې بېرته د مړو نه راژوندی کړ، نو ستاسو فاني وجود ته به هم ژوند ورکړي، ځکه چې دغه روح په تاسو کې هم اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_11.mp3', '', 1761754199, 1761754199),
(33342, 'Romans 8:12', 'Romans', 8, 12, 'نو بیا ای خویندو او ورونو! مونږ مجبوره نه یو چې د انساني فطرت او د هغه د غوښتنو له مخې ژوند وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_12.mp3', '', 1761754199, 1761754199),
(33343, 'Romans 8:13', 'Romans', 8, 13, 'ځکه که چېرې تاسو د خپلو نفساني غوښتنو له مخې ژوند وکړئ، نو مړه به شئ. خو که چېرې د خدای د روح په مرسته خپل د ګناه نه ډک عملونه له منځه یوسئ، نو تاسو به ژوند کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_13.mp3', '', 1761754199, 1761754199),
(33344, 'Romans 8:14', 'Romans', 8, 14, 'ځکه ټول هغه کسان چې د روح په وسیله ورته لارښوونه کیږي، هغوی د خدای اولادونه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_14.mp3', '', 1761754199, 1761754199),
(33345, 'Romans 8:15', 'Romans', 8, 15, 'ځکه چې تاسو هغه روح نه دی تر‌لاسه کړی چې غلامان مو کړي او ستاسو د وېرې سبب شي، بلکې هغه روح مو تر‌لاسه کړ چې تاسو د خدای دپاره لکه د خپلو اولادونو په شان اوسئ او د هغه په وسیله مونږ نارې وهو: «ابا، یعنې ای پلاره»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_15.mp3', '', 1761754199, 1761754199),
(33346, 'Romans 8:16', 'Romans', 8, 16, 'روح القدس په خپله زمونږ د روح سره شاهدي ورکوي چې مونږ د خدای اولادونه یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_16.mp3', '', 1761754199, 1761754199),
(33347, 'Romans 8:17', 'Romans', 8, 17, 'که چېرې مونږ د هغه اولادونه یو، نو بیا وارثان هم یو، یعنې د خدای وارثان یو او د مسیح په میراث کې هم شریک یو او که چېرې مونږ د هغه سره په کړاوونو کې شریک یو، نو د هغه سره په جلال کې هم شریک یو. راتلونکی جلال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_17.mp3', '', 1761754199, 1761754199),
(33348, 'Romans 8:18', 'Romans', 8, 18, 'زه فکر کوم چې هغه کړاوونه چې اوس یې مونږ تېروو، د هغه جلال سره د پرتله کولو وړ نه دي چې مونږ ته به وښودل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_18.mp3', '', 1761754199, 1761754199),
(33349, 'Romans 8:19', 'Romans', 8, 19, 'ځکه چې خلقت په شوق سره د خدای د اولادونو د ښکاره کېدلو په انتظار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_19.mp3', '', 1761754199, 1761754199),
(33350, 'Romans 8:20', 'Romans', 8, 20, 'ځکه چې خلقت بې‌معنی شو، خو په خپله رضا نه بلکې د خدای په رضا، په دې هیله چې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_20.mp3', '', 1761754199, 1761754199),
(33351, 'Romans 8:21', 'Romans', 8, 21, 'یوه ورځ به په خپله خلقت د فساد د غلامۍ نه ازاد شي او د خدای د اولادونو د جلال نه په ډکې ازادۍ کې شامل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_21.mp3', '', 1761754199, 1761754199),
(33352, 'Romans 8:22', 'Romans', 8, 22, 'ځکه چې مونږ پوهېږو چې ټول خلقت یوځای د درد له لاسه لکه د لنګون د درد په شان تر‌اوسه پورې زګېروي کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_22.mp3', '', 1761754199, 1761754199),
(33353, 'Romans 8:23', 'Romans', 8, 23, 'یوازې خلقت نه، بلکې مونږ هم سره له دې چې روح القدس د خدای د لومړني نعمت په توګه تر‌لاسه کړی دی، په خپل باطن کې زګېروي کوو لکه څنګه چې دې ته په شوق سره په انتظار یو چې خدای مونږ د خپلو اولادونو په توګه قبول کړي او زمونږ بدن ته خلاصون ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans8_verse_23.mp3', '', 1761754199, 1761754199),
