(33398, 'John 4:29', 'John', 4, 29, '«راشئ او یو داسې سړی ووینئ چې ما تر‌اوسه پورې هرڅه کړي دي هغه یې راته وویل. کېدای شي چې هغه مسیح وي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_29.mp3', '', 1761754199, 1761754199),
(33399, 'John 4:30', 'John', 4, 30, 'نو هغوی د ښار نه ووتل او عیسی ته ورغلل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_30.mp3', '', 1761754199, 1761754199),
(33400, 'John 4:31', 'John', 4, 31, 'په دې وخت کې شاګردانو د عیسی نه په کلکه وغوښتل: «استاذه، یو څه وخوره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_31.mp3', '', 1761754199, 1761754199),
(33401, 'John 4:32', 'John', 4, 32, 'خو عیسی هغوی ته وویل: «زما سره د خوړلو دپاره داسې خواړه شته چې تاسو ترې هېڅ خبر نه یئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_32.mp3', '', 1761754199, 1761754199),
(33402, 'John 4:33', 'John', 4, 33, 'نو شاګردانو په خپلو کې یو بل ته وویل: «ایا کوم چا هغه ته خواړه راوړي دي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_33.mp3', '', 1761754199, 1761754199),
(33403, 'John 4:34', 'John', 4, 34, 'عیسی هغوی ته وویل: «کله چې زه د هغه چا رضا پوره کړم او د هغه کارونه سرته ورسوم چې زه یې رالېږلی یم، نو دا به زما دپاره داسې وي لکه چې ډوډۍ مې خوړلې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_34.mp3', '', 1761754199, 1761754199),
(33404, 'John 4:35', 'John', 4, 35, 'ایا خلک دا نه وایي: ‹تر‌اوسه لا د لو وخت ته څلور میاشتې پاتې دي.› سترګې خلاصې کړئ او وګورئ چې فصل وختي پوخ شوی دی او لو کولو ته تیار دی!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_35.mp3', '', 1761754199, 1761754199),
(33405, 'John 4:36', 'John', 4, 36, 'لوګري خپله مزدوري اخلي او د تلپاتې ژوندون دپاره حاصل راټولوي، ترڅو کرونکي او لوګري په ګډه سره خوشحالي وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_36.mp3', '', 1761754199, 1761754199),
(33406, 'John 4:37', 'John', 4, 37, 'نو دا رښتیا دي چې خلک وایي: ‹یو یې کري او بل یې رېبي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_37.mp3', '', 1761754199, 1761754199),
(33407, 'John 4:38', 'John', 4, 38, 'ما تاسو ولېږلئ چې د هغو پټیو فصلونه ورېبئ چې تاسو په کې زحمت نه دی ویستلی. نورو زحمت ویستلی او تاسو د هغوی د کار نه ګټه اخلئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_38.mp3', '', 1761754199, 1761754199),
(33408, 'John 4:39', 'John', 4, 39, 'په هغه ښار کې ډېرو سامریانو د هغې ښځې د شاهدۍ له امله چې ویلي یې وو: «ما چې کله هم څه کړي وو هغه ټول یې راته وویل،» نو هغوی په عیسی باندې ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_39.mp3', '', 1761754199, 1761754199),
(33409, 'John 4:40', 'John', 4, 40, 'کله چې سامریان هغه ته راغلل او زارۍ یې ورته وکړلې چې د هغوی سره پاتې شي او عیسی دوه ورځې هلته پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_40.mp3', '', 1761754199, 1761754199),
(33410, 'John 4:41', 'John', 4, 41, 'نورو ډېرو خلکو هم د هغې د خبرو له امله ایمان راوړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_41.mp3', '', 1761754199, 1761754199);